+// Warp-inclusive prefix sum (all 32 lanes participate).
+SGL_DEVICE uint32_t warp_inclusive_sum(uint32_t v) {
+#pragma unroll
+  for (uint32_t d = 1; d < 32; d <<= 1) {
+    const uint32_t n = __shfl_up_sync(0xffffffffu, v, d);
+    if ((threadIdx.x & 31) >= d) v += n;
+  }
+  return v;
+}
